INSERT INTO `v1_950d97f211b0a8ab6d7ab0f4eab3584cf3a45a99fe79cd926d066071543e4299` VALUES (11, "アンナたそアンナたそ！\nおせち料理、美味しそうですぞ！\nさあ、おあがりよ！！", 0, 311, 8, 0, 0.5, 101311, 0, 0, 311010);
