INSERT INTO `v1_950d97f211b0a8ab6d7ab0f4eab3584cf3a45a99fe79cd926d066071543e4299` VALUES (11, "クリスティーナ！\nあなたはいったいどの面下げて\n私たちの前に……", 0, 506, 8, 0, 0.5, 103731, 0, 1, 506013);
INSERT INTO `v1_950d97f211b0a8ab6d7ab0f4eab3584cf3a45a99fe79cd926d066071543e4299` VALUES (3, "nop_06_tomo_talk_anger", 0.2, 506, 1, "", "", 103731, "", "", 506014);
