INSERT INTO `v1_950d97f211b0a8ab6d7ab0f4eab3584cf3a45a99fe79cd926d066071543e4299` VALUES (11, "まあまあ、\nトモちゃんもクリスちゃんも。\nせっかくの新年会なんだから……", 0, 506, 8, 0, 0.5, 104731, 0, 1, 506018);
