INSERT INTO `v1_950d97f211b0a8ab6d7ab0f4eab3584cf3a45a99fe79cd926d066071543e4299` VALUES (11, "この場にいるたくさんの人たちに\nボクの美しさを届けられるのは\nキミのおかげだよ。", 0, 513, 6, 0, 0.5, 100811, 0, 1, 513060);
