INSERT INTO `v1_950d97f211b0a8ab6d7ab0f4eab3584cf3a45a99fe79cd926d066071543e4299` VALUES (11, "さすがショーグン。\nこれなら天下統一も目前デス！", 0, 513, 5, 0, 0.5, 103031, 0, 1, 513072);
