INSERT INTO `v1_950d97f211b0a8ab6d7ab0f4eab3584cf3a45a99fe79cd926d066071543e4299` VALUES (11, "それだチエル君。\nノブレス・オブリージュ──\n大雑把に換言すれば、アキノ君は我々に\n金銭的援助をほどこす義務がある。", 0, 517, 8, 0, 0.5, 111031, 0, 1, 517037);
INSERT INTO `v1_950d97f211b0a8ab6d7ab0f4eab3584cf3a45a99fe79cd926d066071543e4299` VALUES (3, "nop_17_yuni_talk_nofaith", 0.2, 517, 0, 1, "", 111031, 0, "nop_17_yuni_talk_nofaith_loop", 517038);
